using FolderVerse;using Microsoft.Xna.Framework;using Microsoft.Xna.Framework.Graphics;using Microsoft.Xna.Framework.Input;using System.Reflection;
using var game=new MapZoomUi(args[0]);game.Run();
sealed class MapZoomUi(string output):Game1{
 const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;WorldSetup w=null!;SpriteBatch batch=null!;int frame;
 object Get(string n)=>typeof(Game1).GetField(n,F)!.GetValue(this)!;void Set(string n,object v)=>typeof(Game1).GetField(n,F)!.SetValue(this,v);object Call(string n,params object[] a)=>typeof(Game1).GetMethod(n,F)!.Invoke(this,a)!;
 void Check(bool ok,string m){if(!ok)throw new Exception(m);Console.WriteLine("PASS "+m);} protected override void LoadContent(){Window.Position=new(-3000,-3000);AppContext.SetData("APP_CONTEXT_BASE_DIRECTORY",Environment.GetEnvironmentVariable("GAME_RUNTIME"));w=new(){EquipmentMode=RobotEquipmentMode.Materials};w.SetParticipantCounts(1,1);w.SetWorld(1);w.SetCast(2);w.SetPlacement(3);w.Relations.Reset();w.SelectPlayer(0);w.Relations.Leader=0;w.Robots.Initialize(w.Nodes.All.Length,w.ActiveCount);w.Robots.ConfigureFactories(w);w.Salvage.Reset();w.Salvage.EnableExpeditions(w);foreach(var n in w.Nodes.All)n.Owner=0;int h=w.Nodes.All.First(n=>n.Functional).Id;w.ConquerorLocations[0]=w.Nodes.All[h].Cell;w.ConquerorPoints[0]=w.Nodes.All[h].Center;
 foreach(var material in Enum.GetValues<RobotMaterial>()){var robot=w.Robots.Create(0,RobotParts.Complete,RobotRole.Captain) with{HeadMaterial=material,BodyMaterial=(RobotMaterial)(((int)material+1)%9),LegsMaterial=material};w.Robots.Nodes[h].Add(robot);var good=w.Robots.Create(1,RobotParts.Complete) with{HeadMaterial=material,BodyMaterial=material,LegsMaterial=material,IntegratedParts=(int)material%2==0?RobotParts.Head|RobotParts.Body:0};w.Salvage.Items.Add(new(1000+(int)material,h,good));}
 Set("_setup",w);batch=new(GraphicsDevice);var pixel=new Texture2D(GraphicsDevice,1,1);pixel.SetData(new[]{Color.White});Set("_spriteBatch",batch);Set("_pixel",pixel);Content.RootDirectory=Path.Combine(Environment.GetEnvironmentVariable("OLD_RUNTIME")!,"Content");Set("_portraitRenderer",new PortraitRenderer(Content));var fonts=new Microsoft.Xna.Framework.Content.ContentManager(Services,Path.Combine(Environment.GetEnvironmentVariable("PROBE_FONT")!,"Content"));var font=fonts.Load<SpriteFont>("UiFont");Set("_font",font);Set("_ui",Activator.CreateInstance(typeof(Game1).GetField("_ui",F)!.FieldType,batch,pixel,font)!);Set("_conquestAudioUnavailable",true);Set("_screen",Enum.Parse(Get("_screen").GetType(),"WorldStatus"));Check(Math.Abs(CubeNet.MapRobotZoom(50)*2-CubeNet.MapRobotZoom(100))<.001,"zoom follows map scale");}
 protected override void Update(GameTime t){}
 protected override void Draw(GameTime t){
 var net=(CubeNet)Get("_net");var ui=(UiPainter)Get("_ui");var panel=new Rectangle(0,0,1920,1080);net.Home(w);float scale=new[]{32f,64f,128f}[frame];net.SetFitCamera(panel,scale,Vector2.Zero);int home=w.Nodes.All.First(n=>n.Functional).Id;net.Drag(new Vector2(panel.Center.X,panel.Center.Y)-net.NodePosition(w,w.Nodes.All[home],panel));
 using var image=new RenderTarget2D(GraphicsDevice,1920,1080);GraphicsDevice.SetRenderTarget(image);GraphicsDevice.Clear(new Color(16,35,46));batch.Begin();net.DrawMapObjects(ui,w,panel,0);batch.End();GraphicsDevice.SetRenderTarget(null);
 var badges=net.RobotBadges.Where(b=>b.Node==home).ToArray();Check(badges.Length>0,"robots drawn at scale "+scale);var card=badges[0];Check(card.Bounds.Width==(int)(24*CubeNet.MapRobotZoom(scale)),"sprite and hit bounds scale together "+scale);Check(card.Detailed==(scale>=65),"far view simplified; near view detailed "+scale);Check(net.HitRobotBadge(card.Bounds.Center)==home,"visible robot clickable "+scale);
 using(var file=File.Create(Path.Combine(output,$"map-robot-zoom-{frame}.png")))image.SaveAsPng(file,1920,1080);
 if(++frame==3){w.Robots.Check();Console.WriteLine("PASS three map scales rendered, stock unchanged");Exit();}
 }
